## 📌 Stack using Linked List (LIFO – Last In First Out)
```c
#include <stdio.h>
#include <stdlib.h>

// Node structure
struct Node {
    int data;            // store the value
    struct Node* next;   // pointer to the next node
};

// Pointer to top of stack
struct Node* top = NULL;

// Function to push (insert at beginning)
void push(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;        // assign value
    newNode->next = top;          // new node points to old top
    top = newNode;                // update top
    printf("%d pushed to stack\n", value);
}

// Function to pop (remove from beginning)
void pop() {
    if (top == NULL) {
        printf("Stack Underflow! Empty stack\n");
        return;
    }
    struct Node* temp = top;      // store current top
    printf("%d popped from stack\n", temp->data);
    top = top->next;              // move top to next
    free(temp);                   // free old top
}

// Function to display stack
void display() {
    if (top == NULL) {
        printf("Stack is empty\n");
        return;
    }
    struct Node* temp = top;
    printf("Stack: ");
    while (temp != NULL) {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

// Main function
int main() {
    push(10);
    push(20);
    push(30);
    display();     // 30 20 10
    pop();         // removes 30
    display();     // 20 10
    return 0;
}
```

