## 📌 Queue using Linked List (FIFO – First In First Out)
```c
#include <stdio.h>
#include <stdlib.h>

// Node structure
struct Node {
    int data;            // store value
    struct Node* next;   // pointer to next node
};

// Pointers to front and rear of queue
struct Node* front = NULL;
struct Node* rear = NULL;

// Function to enqueue (insert at rear)
void enqueue(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;   // assign value
    newNode->next = NULL;    // last node → next = NULL

    if (rear == NULL) {      // if queue is empty
        front = rear = newNode;
    } else {
        rear->next = newNode;  // link new node at end
        rear = newNode;        // update rear
    }
    printf("%d enqueued to queue\n", value);
}

// Function to dequeue (remove from front)
void dequeue() {
    if (front == NULL) {
        printf("Queue Underflow! Empty queue\n");
        return;
    }
    struct Node* temp = front;   // store front
    printf("%d dequeued from queue\n", temp->data);
    front = front->next;         // move front
    if (front == NULL) rear = NULL; // if queue becomes empty
    free(temp);                  // free old front
}

// Function to display queue
void display() {
    if (front == NULL) {
        printf("Queue is empty\n");
        return;
    }
    struct Node* temp = front;
    printf("Queue: ");
    while (temp != NULL) {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

// Main function
int main() {
    enqueue(10);
    enqueue(20);
    enqueue(30);
    display();    // 10 20 30
    dequeue();    // removes 10
    display();    // 20 30
    return 0;
}
```

---

👉 In short:  
- **Stack:** Insert/delete at **top** (like a plate stack).  
- **Queue:** Insert at **rear**, delete from **front** (like a line of people).  

